from abc import ABC, abstractmethod

class Storage(ABC):
    @abstractmethod
    def save(self, key, value): ...

    @abstractmethod
    def load(self, key): ...

class MemoryStorage(Storage):
    def __init__(self):
        self.data = {}

    def save(self, key, value):
        self.data[key] = value

    def load(self, key):
        return self.data.get(key)

s = MemoryStorage()
s.save('name', 'Alice')
print(s.load('name'))

from typing import Protocol, runtime_checkable

@runtime_checkable
class Greeter(Protocol):
    def greet(self) -> str: ...

class Dog:
    def greet(self) -> str:
        return '汪汪'

class Cat:
    def meow(self) -> str:
        return '喵'

d: Greeter = Dog()
print(d.greet())
print(isinstance(Dog(), Greeter))

from typing import Protocol

class Closable(Protocol):
    def close(self) -> None: ...

class Conn:
    def close(self) -> None:
        print('closed')

c: Closable = Conn()
c.close()

from typing import Protocol

class Exporter(Protocol):
    def export(self, data: dict) -> str: ...

class JsonExporter:
    def export(self, data: dict) -> str:
        return str(data)

def dump(exp: Exporter, data: dict):
    print(exp.export(data))

dump(JsonExporter(), {'a': 1})
